// Configuración: completar DEFAULT_ADMIN_CHAT_ID con el chat id numérico del admin
// (n8n Settings → Error Workflow). Si queda vacío y no hay chat de usuario, no se envía nada.
const DEFAULT_ADMIN_CHAT_ID = $env.DEFAULT_ADMIN_CHAT_ID || '';

const items = $input.all();
const item = items.length > 0 ? items[0] : {};

function findChatId(json) {
  if (!json) return null;
  if (json.id_chat) return json.id_chat;
  if (json.node && json.node.data && Array.isArray(json.node.data)) {
    for (const d of json.node.data) {
      if (d && d.json && d.json.chat && d.json.chat.id) return d.json.chat.id;
    }
  }
  return null;
}

let chatId = findChatId(item.json);
let isAdmin = false;

if (!chatId && DEFAULT_ADMIN_CHAT_ID) {
  chatId = DEFAULT_ADMIN_CHAT_ID;
  isAdmin = true;
}

if (!chatId) {
  // Sin chat de usuario ni admin configurado: no enviar (queda en el execution log).
  return [];
}

const errorData = item.json || {};
const workflow = errorData.workflow || 'desconocido';
const lastNode = errorData.lastNodeExecuted || 'desconocido';
const execId = errorData.executionId || 'desconocido';

const text = isAdmin
  ? '⚠️ Ocurrió un error en el workflow de Aura.\n\nWorkflow: ' + workflow + ' · Nodo: ' + lastNode + ' · Exec: ' + execId
  : '⚠️ Ocurrió un error procesando tu solicitud. Volvé a intentar con /start.';

return [{ json: { chatId, text } }];
